type Section = "dashboard" | "messages" | "listings" | "pricing" | "settings";
type AdminMode = "loading" | "demo" | "live";
type AuthUser = { username: string; role: "admin" | "owner" };

const sectionCopy: Record<Section, { title: string; caption: string }> = {
  dashboard: { title: "Přehled", caption: "Aktuální stav nabídky a poptávek." },
  messages: { title: "Zprávy", caption: "Poptávky z webu na jednom místě." },
  listings: { title: "Inzeráty", caption: "Správa vozidel v nabídce." },
  pricing: { title: "Ceník", caption: "Upravte orientační ceny pro veřejný web." },
  settings: { title: "Nastavení", caption: "Základní údaje a identita webu." },
};

const navigation: Array<{ id: Section; label: string; icon: typeof LayoutDashboard }> = [
  { id: "dashboard", label: "Dashboard", icon: LayoutDashboard },
  { id: "messages", label: "Zprávy", icon: Inbox },
  { id: "listings", label: "Inzeráty", icon: CarFront },
  { id: "pricing", label: "Ceník", icon: CircleDollarSign },
  { id: "settings", label: "Nastavení", icon: Settings },
];

const formatCurrency = (value: number, currency = "Kč") => `${new Intl.NumberFormat("cs-CZ").format(value)} ${currency}`;
const formatDate = (value: string) => new Intl.DateTimeFormat("cs-CZ", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(value));
const statusLabel = (status: CarListing["status"]) => status === "available" ? "Skladem" : "Prodáno";

function cloneBootstrap(): AdminBootstrap {
  return structuredClone(adminMockData);
}

function SectionIcon({ section, size = 18 }: { section: Section; size?: number }) {
  const item = navigation.find((candidate) => candidate.id === section);
  const Icon = item?.icon ?? LayoutDashboard;
  return <Icon size={size} />;
}

function StatusPill({ status }: { status: CarListing["status"] }) {
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold ${status === "available" ? "bg-emerald-50 text-emerald-700 ring-1 ring-inset ring-emerald-200" : "bg-slate-100 text-slate-600 ring-1 ring-inset ring-slate-200"}`}><span className={`size-1.5 rounded-full ${status === "available" ? "bg-emerald-500" : "bg-slate-400"}`} />{statusLabel(status)}</span>;
}

function SourcePill({ source }: { source: ContactMessage["source"] }) {
  const labels = { contact: "Kontakt", reservation: "Rezervace", listing: "Inzerát" };
  return <span className="inline-flex rounded-md bg-slate-100 px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-slate-500">{labels[source]}</span>;
}

function AdminLogin({ onEnter }: { onEnter: (mode: AdminMode, user?: AuthUser) => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [state, setState] = useState<"checking" | "configured" | "unconfigured">("checking");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    adminApi<{ configured: boolean; authenticated: boolean; user?: AuthUser }>("/api/auth/session")
      .then((session) => {
        if (session.authenticated) onEnter("live", session.user);
        else setState(session.configured ? "configured" : "unconfigured");
      })
      .catch(() => setState("unconfigured"));
  }, [onEnter]);

  const login = async (event: React.FormEvent) => {
    event.preventDefault();
    setBusy(true);
    try {
      const user = await adminApi<AuthUser>("/api/auth/login", { method: "POST", body: JSON.stringify({ username, password }) });
      onEnter("live", user);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Přihlášení se nepodařilo.");
    } finally { setBusy(false); }
  };

  return <main className="admin-login min-h-screen bg-[#edf1f5] px-4 py-10 text-slate-900 sm:grid sm:place-items-center">
    <section className="mx-auto block w-full max-w-[560px] overflow-hidden rounded-[28px] bg-[#232727] text-white shadow-[0_28px_90px_rgba(15,23,42,.12)]">
      <div className="hidden">
        <div className="absolute -left-28 top-8 size-80 rounded-full border border-white/10" /><div className="absolute -left-12 top-24 size-80 rounded-full border border-white/10" />
        <div className="relative flex h-full flex-col"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[#e3373b] shadow-lg shadow-red-950/40"><img src="/assets/K2-GARAGE-mlecna.webp" alt="K2 garage" className="h-10 w-auto object-contain" /></span><span className="font-mono text-sm font-bold uppercase tracking-[.18em]">K2 garage Dashboard</span></div>
          <div className="hidden"><p className="mb-5 inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/5 px-3 py-1.5 text-xs font-semibold text-slate-300"><ShieldCheck size={14} className="text-emerald-400" /> Bezpečná administrace</p><h1 className="max-w-md font-sans text-5xl font-semibold leading-[1.06] tracking-tight">Prodej vozů. Bez chaosu.</h1><p className="mt-5 max-w-sm text-base leading-7 text-slate-300">Inzeráty, poptávky, ceník a nastavení vašeho webu na jednom přehledném místě.</p></div>
        </div>
      </div>
      <div className="flex min-h-[610px] flex-col items-center justify-center p-7 text-center sm:p-11"><div className="-mx-7 -mt-7 mb-10 flex w-[calc(100%+3.5rem)] flex-col items-center bg-[#232727] sm:-mx-11 sm:-mt-11 sm:w-[calc(100%+5.5rem)]"><div className="flex min-h-[104px] w-full items-center justify-center"><img src="/assets/K2-GARAGE-mlecna.webp" alt="K2 garage" className="h-12 w-auto object-contain" /></div><div className="h-3 w-full bg-[#232727]" /></div>
        <div><p className="text-sm font-semibold text-[#e3373b]">K2 garage Dashboard</p><h2 className="mt-2 text-3xl font-bold tracking-tight">Vítejte zpět.</h2><p className="mt-3 text-sm leading-6 text-slate-500">Přihlaste se pro správu obsahu veřejného webu.</p></div>
        {state === "checking" ? <div className="mt-10 flex items-center gap-3 text-sm text-slate-500"><LoaderCircle className="animate-spin" size={18} /> Ověřujeme přístup…</div> : state === "configured" ? <form className="mt-9 space-y-5" onSubmit={login}><label className="block text-sm font-semibold text-slate-700">Uživatelské jméno<input value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="username" required className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-slate-900 outline-none transition focus:border-[#e3373b] focus:ring-4 focus:ring-red-100" /></label><label className="block text-sm font-semibold text-slate-700">Heslo<input type="password" value={password} onChange={(event) => setPassword(event.target.value)} autoComplete="current-password" required className="mt-2 w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-slate-900 outline-none transition focus:border-[#e3373b] focus:ring-4 focus:ring-red-100" /></label><p className="text-xs text-slate-400">Přihlásit se může účet ADMIN nebo MAJITEL.</p><button disabled={busy} className="flex w-full items-center justify-center gap-2 rounded-xl bg-[#e3373b] px-4 py-3.5 text-sm font-bold text-white shadow-lg shadow-red-200 transition hover:bg-[#c9282d] disabled:opacity-70">{busy && <LoaderCircle className="animate-spin" size={17} />}{busy ? "Přihlašování…" : "Přihlásit se"}</button></form> : <div className="mt-9 rounded-2xl border border-amber-200 bg-amber-50 p-5"><p className="text-sm font-bold text-amber-900">Administrace čeká na nastavení přístupů</p><p className="mt-2 text-sm leading-6 text-amber-800">Na Vercelu nastavte ADMIN_USERNAME, ADMIN_PASSWORD, OWNER_USERNAME, OWNER_PASSWORD a ADMIN_SESSION_SECRET podle <code className="rounded bg-white/80 px-1.5 py-0.5">.env.example</code>.</p><button onClick={() => onEnter("demo")} className="mt-5 inline-flex items-center gap-2 rounded-xl bg-[#101827] px-4 py-3 text-sm font-bold text-white transition hover:bg-slate-700">Otevřít ukázkový dashboard <ChevronDown className="-rotate-90" size={16} /></button></div>}
      </div>
    </section>
  </main>;
}

